type Review = {
  goal: string;
  prompt: string;
  feedback: string;
};

article.sections.8.blocks.7.text:
function nextPrompt(review: Review): string {
  return [
    `Goal: ${review.goal}`,
    `Previous prompt: ${review.prompt}`,
    `Feedback on the previous attempt: ${review.feedback}`,
    "Revise the result to address this feedback."
  ].join("\n\n");
}

